def toposort(deps):
    from collections import defaultdict, deque

    def dfs(node, visited, stack):
        if visited[node] == 1:
            raise ValueError("Cycle detected")
        if not visited[node]:
            visited[node] = 1
            for neighbor in deps[node]:
                dfs(neighbor, visited, stack)
            visited[node] = 2
            stack.append(node)

    visited = {key: 0 for key in deps}
    stack = []

    for node in deps:
        if not visited[node]:
            dfs(node, visited, stack)

    stack.reverse()
    return stack
