import time
from collections import OrderedDict

class TTLCache:
    def __init__(self, capacity, ttl, clock=time.monotonic):
        if capacity < 1:
            raise ValueError("Capacity must be at least 1")
        if ttl <= 0:
            raise ValueError("TTL must be greater than 0")
        self.capacity = capacity
        self.ttl = ttl
        self.clock = clock
        self.cache = OrderedDict()

    def put(self, key, value):
        current_time = self.clock()
        if key in self.cache:
            del self.cache[key]
        elif len(self.cache) >= self.capacity:
            self.cache.popitem(last=False)
        self.cache[key] = (value, current_time + self.ttl)

    def get(self, key):
        current_time = self.clock()
        if key not in self.cache or self.cache[key][1] < current_time:
            return None
        return self.cache[key][0]

    def __len__(self):
        current_time = self.clock()
        return sum(1 for _, expiry in self.cache.values() if expiry > current_time)

    def keys(self):
        current_time = self.clock()
        return [key for key, (_, expiry) in self.cache.items() if expiry > current_time]
