from heapq import heappush, heappop

class Scheduler:
    def __init__(self):
        self.tasks = defaultdict(list)
        self.errors = []

    def schedule(self, name, run_at, callback, every=None):
        if name in self.tasks:
            raise ValueError(f"Task {name} already exists.")
        if every is not None and every <= 0:
            raise ValueError("Every must be greater than 0.")
        heappush(self.tasks[run_at], (name, callback, every))

    def cancel(self, name):
        for run_at, task_list in self.tasks.items():
            for task in task_list:
                if task[0] == name:
                    task_list.remove(task)
                    return True
        return False

    def pending(self):
        result = []
        for run_at, task_list in sorted(self.tasks.items()):
            for task in task_list:
                result.append((run_at, task[0]))
        return result

    def run_due(self, now):
        run_list = []
        for run_at in sorted(self.tasks.keys()):
            if run_at <= now:
                while self.tasks[run_at]:
                    name, callback, every = heappop(self.tasks[run_at])
                    try:
                        run_list.append(name)
                        if every is not None:
                            next_run_at = run_at + every
                            heappush(self.tasks[next_run_at], (name, callback, every))
                    except Exception as e:
                        self.errors.append((name, e))
        return run_list
