            current_section = line[1:-1].strip()
            if not current_section:
                raise ValueError(f"line {line_number}: empty section header")
            result[current_section] = result.get(current_section, {})
        else:
            if '=' not in line:
                raise ValueError(f"line {line_number}: no '=' in key=value line")

            key, value = map(str.strip, line.split('=', 1))
            key = key.strip()
            if not key:
                raise ValueError(f"line {line_number}: empty key")

            if value.startswith('"') and value.endswith('"'):
                value = value[1:-1].replace('\\"', '"').replace('\\n', '\n').replace('\\t', '\t')
                if not value.endswith((' ', ';', '#')):
                    raise ValueError(f"line {line_number}: unterminated quoted value")
            else:
                value = value.split(';', 1)[0].split('#', 1)[0].strip()
                if not value:
                    raise ValueError(f"line {line_number}: empty value")

            result[current_section][key] = value

    return result
