import heapq

def shortest_path(graph, src, dst):
    if src not in graph and src not in {neigh for neigh in graph.values()}:
        raise ValueError(f"Source node {src} not found in the graph.")
    if dst not in graph and dst not in {neigh for neigh in graph.values()}:
        raise ValueError(f"Destination node {dst} not found in the graph.")

    for neigh, weight in graph.values():
        if weight <= 0:
            raise ValueError("Graph contains non-positive weights.")

    if src == dst:
        return (0, [src])

    queue = [(0, src, [src])]
    visited = set()

    while queue:
        cost, node, path = heapq.heappop(queue)

        if node in visited:
            continue
        visited.add(node)

        if node == dst:
            return (cost, path)

