        cost, node, path = heapq.heappop(queue)

        if node in visited:
            continue
        visited.add(node)

        if node == dst:
            return (cost, path)

        for neigh, weight in graph.get(node, {}).items():
            if neigh not in visited:
                heapq.heappush(queue, (cost + weight, neigh, path + [neigh])

